#if canImport(SwiftUI) && os(iOS)
  import CoreText
  import Foundation
  import os
  import UIKit

  /// The phone's fonts. Inter Regular and SemiBold are bundled in this package (static TrueType
  /// instances generated by tools/brand/generate_plan_brand.py) and registered at runtime for this
  /// process; Times New Roman ships with iOS. `UIAppFonts` is not used: it cannot see a package's
  /// bundle.
  public enum ChapterFonts {
    /// PostScript names.
    public static let interRegular = "Inter-Regular"
    public static let interSemiBold = "Inter-SemiBold"
    public static let timesRegular = "TimesNewRomanPSMT"

    /// The bundled font files, in registration order.
    public static var fontURLs: [URL] {
      [interRegular, interSemiBold].compactMap { name in
        Bundle.module.url(forResource: name, withExtension: "ttf")
          ?? Bundle.module.url(forResource: name, withExtension: "ttf", subdirectory: "Fonts")
      }
    }

    private static let registration = OSAllocatedUnfairLock(initialState: false)

    /// Registers the bundled Inter fonts for this process. Call it at launch and in the setUp of
    /// every snapshot test. Idempotent: a second call, or fonts that are already registered, is
    /// not an error. Returns whether both Inter faces are available afterwards.
    @discardableResult
    public static func register() -> Bool {
      registration.withLock { registered in
        guard !registered else { return }
        for failure in registerFiles(fontURLs) {
          Logger(subsystem: "com.hellochapter.ChapterUI", category: "fonts")
            .error("Could not register \(failure, privacy: .public)")
        }
        registered = true
      }
      return isAvailable
    }

    /// Registers each file for this process and returns the files that failed, as
    /// "<file name>: <CTFontManagerError code>". A file that is already registered did not fail.
    static func registerFiles(_ urls: [URL]) -> [String] {
      urls.compactMap { url in
        var error: Unmanaged<CFError>?
        if CTFontManagerRegisterFontsForURL(url as CFURL, .process, &error) { return nil }
        let code = error.map { CFErrorGetCode($0.takeRetainedValue()) } ?? 0
        if code == CTFontManagerError.alreadyRegistered.rawValue { return nil }
        return "\(url.lastPathComponent): \(code)"
      }
    }

    /// Whether Inter Regular and SemiBold can be used by name.
    public static var isAvailable: Bool {
      UIFont(name: interRegular, size: 17) != nil && UIFont(name: interSemiBold, size: 17) != nil
    }
  }
#endif
